#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" && grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "header or other booking removed"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] && [ -z "$o" ] || { echo "not found should exit 1 with empty stdout: exit $rc, stdout [$o]"; fail=1; }
o=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] && [ -z "$o" ] || { echo "usage should exit 2 with empty stdout: exit $rc, stdout [$o]"; fail=1; }
printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "other room's booking removed"; fail=1; }
rm -f "$t"; exit $fail

